//! Byte-exact StandardTokenizer parity against Lucene's own test expectations.
//! Data: es-index/tests/data/*.jsonl, regenerated by scripts/extract_lucene_analysis_tests.py.

use es_index::analysis::{Analyzer, standard_tokenize};

fn check(file: &str) {
    let data = std::fs::read_to_string(format!("{}/tests/data/{file}", env!("CARGO_MANIFEST_DIR")))
        .unwrap();
    let mut failures = Vec::new();
    let mut total = 0;
    for line in data.lines() {
        let (input, expected): (String, Vec<String>) = serde_json::from_str(line).unwrap();
        total += 1;
        let actual = standard_tokenize(&input);
        if actual != expected {
            failures.push(format!(
                "{input:?}\n  expected {expected:?}\n  actual   {actual:?}"
            ));
        }
    }
    let shown: Vec<_> = failures.iter().take(15).collect();
    assert!(
        failures.is_empty(),
        "{file}: {}/{total} failed\n{}",
        failures.len(),
        shown
            .iter()
            .map(|s| s.as_str())
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn standard_analyzer_cases() {
    check("lucene_standard_analyzer.jsonl");
}

#[test]
fn unicode_12_1_word_breaks() {
    check("lucene_word_break_12_1.jsonl");
}

#[test]
fn unicode_12_1_emoji() {
    check("lucene_emoji_12_1.jsonl");
}

/// From Lucene's TestStandardAnalyzer.testMaxTokenLengthDefault: tokens split at 255 chars.
#[test]
fn max_token_length_default() {
    let b = "b".repeat(255);
    let input = format!("x {b} {b}b");
    assert_eq!(standard_tokenize(&input), vec!["x", &b, &b, "b"]);
}

/// Lucene's LowerCaseFilter lowercases per code point (Character.toLowerCase), not
/// with full Unicode special casing: no final-sigma rule, and İ becomes plain i.
#[test]
fn standard_analyzer_lowercases_per_code_point() {
    assert_eq!(
        Analyzer::Standard.analyze("The QUICK İstanbul ΣΟΦΟΣ"),
        vec!["the", "quick", "istanbul", "σοφοσ"]
    );
}

#[test]
fn standard_analyzer_keeps_stopwords() {
    assert_eq!(
        Analyzer::Standard.analyze("to be or not"),
        vec!["to", "be", "or", "not"]
    );
}

#[test]
fn keyword_analyzer_is_identity() {
    assert_eq!(
        Analyzer::Keyword.analyze("Hello, World!"),
        vec!["Hello, World!"]
    );
    assert_eq!(Analyzer::Keyword.analyze(""), vec![""]);
}
